window.SNPluginsUtils = class SNPluginsUtils {
  isJSONObject(str) {
    if (typeof str !== 'string') return false;

    try {
      const parsed = JSON.parse(str);
      return typeof parsed === 'object' && parsed !== null && !Array.isArray(parsed);
    } catch (e) {
      return false;
    }
  }

  makeJSONFlagStyle(){
    return 'font-size: 0.75em; '+
    	'font-family: "san-serif"; '+
      'background-color:orange; '+
      'color: black; '+
        'margin-left: 5px; '+
        'padding: 2px;';
  }
}

function addJSONFlag(field, field_json) {
    SNPlugins.console("field=" + JSON.stringify(field, null, 2) + "\nfield_json=" + field_json);
    const labelId = `label.${field.tableName}.${field.fieldName}`;
    const selector = `#${CSS.escape(labelId)}`;
    const formatted_json = JSON.stringify(JSON.parse(field_json), null, 2);
    const window_content = `<pre>${formatted_json}</pre>`;
    //const window_content="<pre>"+JSON.strinfgify(g_form.getValue(field.fieldName),null,2)+"</pre>";
    SNPlugins.addInsideBefore(selector, {
        "id": "json-for-" + field.fieldName,
        "tag": "span",
        "textContent": "JSON",
        "attrs": {
            "style": new SNPluginsUtils().makeJSONFlagStyle()
        },
        onclick(e) {
            const btn = e.currentTarget;
            const myWindow = window.open("", "", "width=300,height=300");
            myWindow.document.write(`${window_content}`);
        }
    });
}

SNPlugins.onRouteChange(async () => {
    try {
        const record = SNPlugins.getRecord();
        if (!record || record.isWorkspace) return;
        const form = await SNPlugins.waitForLoaded();

        const tools = new SNPluginsUtils();
        var g_form = SNPlugins.g_form();
        var fields = g_form.elements;
        fields.forEach(function(field) {
            if (field.type == "string") {
                if (tools.isJSONObject(g_form.getValue(field.fieldName))) {
                    //g_form.showFieldMsg(field.fieldName,"IS JSON");
                    addJSONFlag(field, g_form.getValue(field.fieldName));

                }
            } else if (field.type == "json") {
                const json_value = g_form.getValue(field.fieldName);
                if (json_value != '' && (typeof json_value) == 'string') {
                    addJSONFlag(field, g_form.getValue(field.fieldName));
                }
            }
        });
    } catch (e) {
        SNPlugins.console(e.message, "error");
    }
});

